import{_ as a,o as s,c as i,a0 as e}from"./chunks/framework.DoRPXVp_.js";const k=JSON.parse('{"title":"Lattice 部署指南（个人/家庭模式）","description":"","frontmatter":{},"headers":[],"relativePath":"deploy-personal-mode.md","filePath":"deploy-personal-mode.md"}'),l={name:"deploy-personal-mode.md"};function n(d,t,o,h,r,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="lattice-部署指南-个人-家庭模式" tabindex="-1">Lattice 部署指南（个人/家庭模式） <a class="header-anchor" href="#lattice-部署指南-个人-家庭模式" aria-label="Permalink to &quot;Lattice 部署指南（个人/家庭模式）&quot;">​</a></h1><blockquote><p>适用: standalone 模式自托管部署（家庭局域网 + 出门访问） 读者: 自部署用户与家庭管理员 关联: <code>docs/latticedns-technical.md</code>（LatticeDNS 原理）、<code>docs/superpowers/specs/2026-09-17-latticedns-design.md</code> 合规摘要见 §七（自托管自用的边界；商业化运营需另行取得法律意见）</p></blockquote><hr><h2 id="〇、一条黄金法则" tabindex="-1">〇、一条黄金法则 <a class="header-anchor" href="#〇、一条黄金法则" aria-label="Permalink to &quot;〇、一条黄金法则&quot;">​</a></h2><blockquote><p><strong>所有&quot;下发给设备&quot;的地址（信令、二维码、接入指引），必须是设备能访问到的地址——不是服务器自己的回环地址。</strong></p></blockquote><p>服务器上 <code>127.0.0.1:18090</code> 自己能打开，不代表手机能连上。本次真机联调的第一堵墙就是它。</p><hr><h2 id="一、端口与地址总表" tabindex="-1">一、端口与地址总表 <a class="header-anchor" href="#一、端口与地址总表" aria-label="Permalink to &quot;一、端口与地址总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>协议</th><th>用途</th><th>绑定</th></tr></thead><tbody><tr><td><code>listen</code>（默认 <code>:8080</code>）</td><td>TCP</td><td>管理 API + Web 控制台 + 入网二维码</td><td>见 §二</td></tr><tr><td>4222</td><td>TCP</td><td>NATS 信令（设备注册/拓扑推送）</td><td>所有接口</td></tr><tr><td>6266</td><td>TCP/UDP</td><td>LRP 中继（打洞失败时的兜底通道）</td><td>所有接口</td></tr><tr><td>51820/udp</td><td>UDP</td><td>WireGuard 数据面（引擎，按需）</td><td>引擎</td></tr><tr><td>3478</td><td>UDP</td><td>STUN（如启用自有 STUN）</td><td>配置</td></tr></tbody></table><hr><h2 id="二、三个必须理解的地址" tabindex="-1">二、三个必须理解的地址 <a class="header-anchor" href="#二、三个必须理解的地址" aria-label="Permalink to &quot;二、三个必须理解的地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>配置键</th><th>作用</th><th>常见错误</th></tr></thead><tbody><tr><td><strong>监听地址</strong></td><td><code>listen</code> / <code>LATTICE_LISTEN</code></td><td>latticed API 绑定的地址与端口</td><td>绑定回环后局域网设备访问不了</td></tr><tr><td><strong>信令地址</strong></td><td><code>signaling-url</code> / <code>LATTICE_SIGNALING_URL</code></td><td>下发给设备的 NATS 地址</td><td>⚠️ 留空时兜底 <code>nats://127.0.0.1:4222</code>——<strong>外部设备永远连不上</strong></td></tr><tr><td><strong>服务地址</strong></td><td>dashboard 的访问地址</td><td>入网二维码编码的服务器地址</td><td>用 <code>127.0.0.1</code> 打开控制台 → 二维码里也是回环地址</td></tr></tbody></table><p><strong>symptom 速查</strong>：App 点&quot;连接&quot;一闪回到&quot;未连接&quot; = 十有八九是信令地址问题（详见 §六故障表）。</p><hr><h2 id="三、三种典型部署拓扑" tabindex="-1">三、三种典型部署拓扑 <a class="header-anchor" href="#三、三种典型部署拓扑" aria-label="Permalink to &quot;三、三种典型部署拓扑&quot;">​</a></h2><h3 id="拓扑-a-纯家庭内网使用-设备回家才用" tabindex="-1">拓扑 A：纯家庭内网使用（设备回家才用） <a class="header-anchor" href="#拓扑-a-纯家庭内网使用-设备回家才用" aria-label="Permalink to &quot;拓扑 A：纯家庭内网使用（设备回家才用）&quot;">​</a></h3><p>最简部署，无需公网、无需 VPS：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># lattice.yaml 关键项</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.1.8:18090&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 绑定局域网地址（或 0.0.0.0）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">signaling-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nats://192.168.1.8:4222&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # ⚠️ 必填：局域网可达的 NATS 地址</span></span></code></pre></div><ul><li>设备（手机/电脑）连家庭 Wi-Fi，App 扫码/手动填 <code>http://192.168.1.8:18090</code> 加入；</li><li>出门后回到家用 Wi-Fi 自动重连。</li></ul><h3 id="拓扑-b-出门随时可用-——-ipv6-直连-推荐-零暴露" tabindex="-1">拓扑 B：出门随时可用 —— IPv6 直连（推荐，零暴露） <a class="header-anchor" href="#拓扑-b-出门随时可用-——-ipv6-直连-推荐-零暴露" aria-label="Permalink to &quot;拓扑 B：出门随时可用 —— IPv6 直连（推荐，零暴露）&quot;">​</a></h3><p>国内家宽与蜂窝网络 IPv6 普及率已很高。<strong>两端都有 IPv6 = 天然公网地址直连，无需打洞、无需中继</strong>。</p><p>要求：</p><ol><li>家里宽带开启 IPv6（光猫改桥接/路由器开启 IPv6）；</li><li>家里设备（NAS/Mac）的防火墙放行 WireGuard 端口（51820/udp）给指定来源；</li><li>出门设备（蜂窝/Wi-Fi）同样具备 IPv6。</li></ol><p>IPv4 兜底（无 IPv6 环境时）：路由器端口转发 UDP 51820 → 家里设备，或参考拓扑 C。</p><h3 id="拓扑-c-出门随时可用-——-ipv4-自部署中继兜底" tabindex="-1">拓扑 C：出门随时可用 —— IPv4 + 自部署中继兜底 <a class="header-anchor" href="#拓扑-c-出门随时可用-——-ipv4-自部署中继兜底" aria-label="Permalink to &quot;拓扑 C：出门随时可用 —— IPv4 + 自部署中继兜底&quot;">​</a></h3><ol><li>路由器端口转发 UDP 51820 → 家里设备（IPv4 直连路径）；</li><li>打洞失败时的兜底：<strong>自部署 LRP 中继</strong>（<code>lrper</code>）到你有公网的 VPS：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># VPS 上（有公网 IP）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./lrper</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :6266</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 家里 lattice.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">relay-url:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你VPS的IP:6266&quot;</span></span></code></pre></div><blockquote><p><strong>合规边界</strong>：官方不运营任何中继节点；lrper 是自部署组件，使用者自行确保用途合规（不承载跨境信道、不面向公众提供服务）。商业化组网服务需电信业务牌照。</p></blockquote><hr><h2 id="四、参考配置-带注释的-lattice-yaml" tabindex="-1">四、参考配置（带注释的 lattice.yaml） <a class="header-anchor" href="#四、参考配置-带注释的-lattice-yaml" aria-label="Permalink to &quot;四、参考配置（带注释的 lattice.yaml）&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 管理/API 监听地址</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:18090&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 仅本机访问控制台时用回环；需要局域网访问则绑 LAN IP</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ⚠️ 信令地址：下发给设备的 NATS 地址。必须留空以外的值——</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 留空时兜底 nats://127.0.0.1:4222，外部设备会连向它自己。</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">signaling-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nats://192.168.1.8:4222&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># STUN：留空时使用内置多服务器列表（自有 + 国内公共 + 全球双栈）。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 如自建 STUN 可在此指定，将作为列表首位优先使用。</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stun-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># LRP 中继（拓扑 C 的自部署中继）：none 时仅打洞直连</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">relay-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>环境变量等价（viper 自动绑定，<code>LATTICE_</code> 前缀）：<code>LATTICE_LISTEN</code>、<code>LATTICE_SIGNALING_URL</code>、<code>LATTICE_STUN_URL</code>。</p><hr><h2 id="五、入网二维码与服务器地址语义" tabindex="-1">五、入网二维码与服务器地址语义 <a class="header-anchor" href="#五、入网二维码与服务器地址语义" aria-label="Permalink to &quot;五、入网二维码与服务器地址语义&quot;">​</a></h2><p>控制台「令牌页 → 行菜单 → 入网二维码」生成的码，编码内容为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lattice://join?server=&lt;控制台访问地址&gt;&amp;token=&lt;令牌值&gt;</span></span></code></pre></div><ul><li><strong>控制台地址 = 手机将使用的服务器地址</strong>。用 <code>http://192.168.1.8:18090</code> 打开控制台，码里就是局域网地址（回家 Wi-Fi 可用）；用 VPS 域名打开，码里就是 VPS 地址（出门可用）；</li><li>二维码弹窗中会显示实际编码的服务器地址，<strong>出码前请核对其中的地址是手机可达的</strong>；</li><li>同一令牌默认 7 天有效、最多 5 台设备使用（生成时可在控制台调整）。</li></ul><hr><h2 id="六、故障对照表-真实症状-→-原因-→-处理" tabindex="-1">六、故障对照表（真实症状 → 原因 → 处理） <a class="header-anchor" href="#六、故障对照表-真实症状-→-原因-→-处理" aria-label="Permalink to &quot;六、故障对照表（真实症状 → 原因 → 处理）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>App 点连接一闪回到&quot;未连接&quot;</td><td>信令地址是回环（127.0.0.1）</td><td>设 <code>signaling-url</code> 为局域网/公网可达的 NATS 地址</td></tr><tr><td>扫码后无法连接 / 连接超时</td><td>二维码里的服务器地址手机不可达</td><td>用手机可达的地址重新打开控制台再出码</td></tr><tr><td>设备列表质量标签一直&quot;连接中&quot;</td><td>探测对端不可达</td><td>检查对端是否在线；满 60 秒转&quot;不可达&quot;</td></tr><tr><td>面板/列表无质量标签</td><td>探测数据未就绪（刚连上 15 秒内属正常）</td><td>等待探测周期；仍无则检查隧道是否已连接</td></tr><tr><td>退出网络后首页仍显示&quot;登录后可查看设备&quot;</td><td>旧版本退出未删除 VPN 配置</td><td>升级到包含 <code>removeProfile</code> 的版本后重新退出一次</td></tr></tbody></table><hr><h2 id="七、合规边界摘要" tabindex="-1">七、合规边界摘要 <a class="header-anchor" href="#七、合规边界摘要" aria-label="Permalink to &quot;七、合规边界摘要&quot;">​</a></h2><ul><li>自托管、自使用：合法（与 WireGuard/ZeroTier 等开源组网工具同类）；</li><li>官方<strong>不运营</strong>任何中继/节点；lrper 为用户自部署组件；</li><li><strong>不承载跨境信道</strong>；面向公众的组网/通信服务需电信业务牌照；</li><li>本文档为工程合规摘要，不构成法律意见；商业化前请咨询专业律师。</li></ul>`,43)])])}const u=a(l,[["render",n]]);export{k as __pageData,u as default};
